window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-17091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαιμονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5852 na letra ε · nº geral 17091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 felicidade; prosperidade 2 riqueza; abundância de bens; fortuna. 〈εὐδαίμων〉</p></section></article>\n<article id=\"entry-dgp-17092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαιμονίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 5853 na letra ε · nº geral 17092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., fut. e aor.) 1 julgar ou declarar feliz; felicitar alguém, ac., por algo, gen. ou ὑπέρ e gen. ou ἐπί e dat. ou διά e ac. 2 ser feliz. 〈εὐδαίμων〉</p></section></article>\n<article id=\"entry-dgp-17093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαιμονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5854 na letra ε · nº geral 17093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da felicidade 2 feliz 3 que torna feliz. 〈εὐδαίμων〉</p></section></article>\n<article id=\"entry-dgp-17094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαιμονικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 5855 na letra ε · nº geral 17094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo feliz.</p></section></article>\n<article id=\"entry-dgp-17095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαιμονισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5856 na letra ε · nº geral 17095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o considerar alguém feliz 2 favor da fortuna; felicidade 3 reputação de felicidade. 〈εὐδαιμονίζω〉</p></section></article>\n<article id=\"entry-dgp-17096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαιμόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 5857 na letra ε · nº geral 17096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo feliz; na felicidade; na prosperidade.</p></section></article>\n<article id=\"entry-dgp-17097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδαίμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5858 na letra ε · nº geral 17097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 feliz; afortunado 2 rico; opulento; próspero ♦ τὸ εὔδαιμον 3 a felicidade. 〈εὖ, δαίμων〉</p></section></article>\n<article id=\"entry-dgp-17098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδάκρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5859 na letra ε · nº geral 17098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que causa muitas lágrimas. 〈εὖ, δακρύω〉</p></section></article>\n<article id=\"entry-dgp-17099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδάπανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5860 na letra ε · nº geral 17099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gasta muito; generoso 2 comprado a preço baixo. 〈εὖ, δαπάνη〉</p></section></article>\n<article id=\"entry-dgp-17100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδείελος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5861 na letra ε · nº geral 17100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se percebe de longe; bem visível; claro; distinto. 〈εὖ, δέελος〉</p></section></article>\n<article id=\"entry-dgp-17101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδειπνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5862 na letra ε · nº geral 17101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de mesa farta; lauto 2 venerado com banquete (em funeral). 〈εὖ, δεῖπνον〉</p></section></article>\n<article id=\"entry-dgp-17102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑδέμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 5863 na letra ε · nº geral 17102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de εὕδω.</p></section></article>\n<article id=\"entry-dgp-17103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδενδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5864 na letra ε · nº geral 17103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem arborizado; rico em plantas. 〈εὖ, δένδρον〉</p></section></article>\n<article id=\"entry-dgp-17104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕδεσκε</h1><div class=\"entry-meta\"><span>DGP · ordem 5865 na letra ε · nº geral 17104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de εὕδω.</p></section></article>\n<article id=\"entry-dgp-17105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5866 na letra ε · nº geral 17105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem visível; bem claro 2 manifesto; evidente. 〈εὖ, δῆλος〉</p></section></article>\n<article id=\"entry-dgp-17106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδήλως</h1><div class=\"entry-meta\"><span>DGP · ordem 5867 na letra ε · nº geral 17106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. evidentemente.</p></section></article>\n<article id=\"entry-dgp-17107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕδῃσθα</h1><div class=\"entry-meta\"><span>DGP · ordem 5868 na letra ε · nº geral 17107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. pres. subj. ép. de εὕδω.</p></section></article>\n<article id=\"entry-dgp-17108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5869 na letra ε · nº geral 17108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bom tempo; céu sereno 2 calma; serenidade de espírito. 〈εὔδιος〉</p></section></article>\n<article id=\"entry-dgp-17109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάβατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5870 na letra ε · nº geral 17109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de atravessar. 〈εὖ, διαβαίνω〉</p></section></article>\n<article id=\"entry-dgp-17110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάβλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5871 na letra ε · nº geral 17110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐδιάβολος. 〈εὖ, διαβάλλω〉</p></section></article>\n<article id=\"entry-dgp-17111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάβολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5872 na letra ε · nº geral 17111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de apresentar falsamente ou de interpretar mal 2 que se presta facilmente à calúnia. 〈εὖ, διαβάλλω〉</p></section></article>\n<article id=\"entry-dgp-17112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιαῖος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5873 na letra ε · nº geral 17112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">buraco do esgoto. 〈εὔδιος〉</p></section></article>\n<article id=\"entry-dgp-17113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιαίτερος</h1><div class=\"entry-meta\"><span>DGP · ordem 5874 na letra ε · nº geral 17113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εὔδιος.</p></section></article>\n<article id=\"entry-dgp-17114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδίαιτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5875 na letra ε · nº geral 17114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">temperante; moderado. 〈εὖ, δίαιτα〉</p></section></article>\n<article id=\"entry-dgp-17115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάλλακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5876 na letra ε · nº geral 17115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de reconciliar, de aplacar; conciliador. 〈εὖ, διαλλάσσω〉</p></section></article>\n<article id=\"entry-dgp-17116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιαλλάκτως</h1><div class=\"entry-meta\"><span>DGP · ordem 5877 na letra ε · nº geral 17116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo conciliador; com indulgência.</p></section></article>\n<article id=\"entry-dgp-17117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάλυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5878 na letra ε · nº geral 17117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de digerir 2 fácil de destruir, de desunir, de interromper 3 fácil de refutar 4 fácil de reconciliar. 〈εὖ, διαλύω〉</p></section></article>\n<article id=\"entry-dgp-17118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάναξ, άνακτος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5879 na letra ε · nº geral 17118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">senhor do tempo sereno. 〈εὐδία, ἄναξ〉</p></section></article>\n<article id=\"entry-dgp-17119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιάχυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5880 na letra ε · nº geral 17119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de liquifazer, de dissolver. 〈εὖ, διαχέω〉</p></section></article>\n<article id=\"entry-dgp-17120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδιήγητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5881 na letra ε · nº geral 17120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de contar, de narrar. 〈εὖ, διη­γέομαι〉</p></section></article>\n<article id=\"entry-dgp-17121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5882 na letra ε · nº geral 17121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">retidão; justiça. 〈εὖ, δίκη〉</p></section></article>\n<article id=\"entry-dgp-17122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5883 na letra ε · nº geral 17122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calmo; tranqüilo; sereno (vento) 2 ao abrigo do vento ou do mau tempo. 〈εὖ, δῖος〉</p></section></article>\n<article id=\"entry-dgp-17123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5884 na letra ε · nº geral 17123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem construído. 〈εὖ, δέμω〉</p></section></article>\n<article id=\"entry-dgp-17124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5885 na letra ε · nº geral 17124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 julgar bom; aprovar; estar satisfeito com algo, dat. ou ac. ou ἐν e dat. ou inf. ou part. 2 aquiescer ao desejo de alguém, dat. ou ἐπί e dat. ou εἰς e ac. ♦ méd. 3 estar contente; comprazer-se com algo, dat. ou ἐπί e dat. 〈εὖ, δοκέω〉</p></section></article>\n<article id=\"entry-dgp-17125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδοκία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5886 na letra ε · nº geral 17125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. boa vontade. 〈εὐδοκέω〉</p></section></article>\n<article id=\"entry-dgp-17126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδοκιμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5887 na letra ε · nº geral 17126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ηὐδοκίμουν, fut. εὐδοκιμήσω, aor. ηὐδοκίμησα, perf. ηὐδοκίμηκα) 1 ser estimado, honrado; ter boa reputação; ter renome 2 (coisa) ser valorizado; ser apreciado 3 ter valor; ser genuíno. 〈εὐδόκιμος〉</p></section></article>\n<article id=\"entry-dgp-17127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδοκίμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5888 na letra ε · nº geral 17127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">boa reputação; renome; consideração. 〈εὐδοκιμέω〉</p></section></article>\n<article id=\"entry-dgp-17128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδόκιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5889 na letra ε · nº geral 17128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que desfruta de boa reputação; considerado; estimado 2 ilustre; célebre; honrado. 〈εὖ, δόκιμος〉</p></section></article>\n<article id=\"entry-dgp-17129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδοξέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5890 na letra ε · nº geral 17129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter boa reputação; ter renome; ser estimado ou renomado. 〈εὔδοξος〉</p></section></article>\n<article id=\"entry-dgp-17130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδοξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5891 na letra ε · nº geral 17130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 boa reputação; celebridade; glória 2 aprovação; consenso 3 bom senso; juízo. 〈εὔδοξος〉</p></section></article>\n<article id=\"entry-dgp-17131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδοξος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5892 na letra ε · nº geral 17131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que goza de boa reputação; renomado; célebre; glorioso. 〈εὖ, δόξα〉</p></section></article>\n<article id=\"entry-dgp-17132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδρακής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5893 na letra ε · nº geral 17132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de olhar penetrante; que vê claro; que vê de longe; que distingue. 〈εὖ, δέρκομαι〉</p></section></article>\n<article id=\"entry-dgp-17133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδρομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5894 na letra ε · nº geral 17133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">correr rapidamente. 〈εὖ, δρόμος〉</p></section></article>\n<article id=\"entry-dgp-17134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδρομίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5895 na letra ε · nº geral 17134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bom corredor, espécie de peixe. 〈εὖ, δρόμος〉</p></section></article>\n<article id=\"entry-dgp-17135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔδροσος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5896 na letra ε · nº geral 17135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">úmido de orvalho; úmido. 〈εὖ, δρόσος〉</p></section></article>\n<article id=\"entry-dgp-17136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐδυσώπητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5897 na letra ε · nº geral 17136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se deixa intimidar com facilidade; que se envergonha; tímido condescendente. 〈εὖ, δυσωπέω〉</p></section></article>\n<article id=\"entry-dgp-17137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕδω</h1><div class=\"entry-meta\"><span>DGP · ordem 5898 na letra ε · nº geral 17137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. poét. εὗδον, át. ηὗδον) 1 dormir; repousar 2 acalmar-se; apaziguar-se.</p></section></article>\n<article id=\"entry-dgp-17138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔεδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5899 na letra ε · nº geral 17138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sentado em belo assento, em trono 2 cômodo para sentar (cavalo) 3 que se manifesta favoravelmente; que se põe à direita, i.e., de bom augúrio (pássaro). 〈εὖ, ἕδρα〉</p></section></article>\n<article id=\"entry-dgp-17139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5900 na letra ε · nº geral 17139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de aspecto agradável; belo; gracioso. 〈εὖ, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-17140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐείμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5901 na letra ε · nº geral 17140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος bem vestido. 〈εὖ, εἷμα〉</p></section></article>\n<article id=\"entry-dgp-17141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐέκτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5902 na letra ε · nº geral 17141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de boa constituição; vigoroso. 〈εὖ, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-17142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεκτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5903 na letra ε · nº geral 17142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem constituído; em boa saúde; sadio; são 2 que deixa disposto; salutar. 〈εὔεκτος〉</p></section></article>\n<article id=\"entry-dgp-17143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔεκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5904 na letra ε · nº geral 17143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐέκτης.</p></section></article>\n<article id=\"entry-dgp-17144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐέλεγκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5905 na letra ε · nº geral 17144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de contradizer ou refutar 2 fácil de verificar. 〈εὖ, ἐλέγχω〉</p></section></article>\n<article id=\"entry-dgp-17145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔελπις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 5906 na letra ε · nº geral 17145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ιδος, ac. -ιν 1 cheio de esperança; confiante; otimista; esperançoso de algo, gen. ou dat. ou ἐπί e dat., περί e gen., πρός e ac., ou inf.: εὐέλπιδες ὄντες σωθήσεται tuc. estando esperançosos de serem salvos 2 que permite esperar; que dá esperança; que torna esperançoso ♦ τὸ εὔελπι 3 boa esperança. 〈εὖ, ἐλπίς〉</p></section></article>\n<article id=\"entry-dgp-17146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐελπιστία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5907 na letra ε · nº geral 17146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">total confiança; otimismo.</p></section></article>\n<article id=\"entry-dgp-17147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεξάλειπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5908 na letra ε · nº geral 17147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de anular, de cancelar. 〈εὖ, ἐξαλείφω〉</p></section></article>\n<article id=\"entry-dgp-17148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεξαπάτητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5909 na letra ε · nº geral 17148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de enganar. 〈εὖ, ἐξαπατάω〉</p></section></article>\n<article id=\"entry-dgp-17149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐέξαπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5910 na letra ε · nº geral 17149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de acender, de inflamar; facilmente inflamável. 〈εὖ, ἐξάπτω2〉</p></section></article>\n<article id=\"entry-dgp-17150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐυεξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5911 na letra ε · nº geral 17150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 boa constituição corporal; boa saúde 2 vigor; robustez. 〈εὔεκτος〉</p></section></article>\n<article id=\"entry-dgp-17151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐέξοδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5912 na letra ε · nº geral 17151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de onde se foge com facilidade 2 que escapa facilmente (água). 〈εὖ, ἔξοδος〉</p></section></article>\n<article id=\"entry-dgp-17152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεπακολούθητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5913 na letra ε · nº geral 17152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de seguir. 〈εὖ, ἐπακολουθέω〉</p></section></article>\n<article id=\"entry-dgp-17153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐέπεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5914 na letra ε · nº geral 17153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 talento oratório; eloqüência 2 palavra gentil; cortesia. 〈εὖ, εὐεπής〉</p></section></article>\n<article id=\"entry-dgp-17154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5915 na letra ε · nº geral 17154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem dito; bem expresso; elegante 2 melodioso agradável (voz). 〈εὖ, ἔπος〉</p></section></article>\n<article id=\"entry-dgp-17155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεπίβατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5916 na letra ε · nº geral 17155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de subir, de escalar. 〈εὖ, ἐπιβαίνω〉</p></section></article>\n<article id=\"entry-dgp-17156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεπιβούλευτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5917 na letra ε · nº geral 17156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exposto às emboscadas, aos ataques. 〈εὖ, ἐπιβουλεύω〉</p></section></article>\n<article id=\"entry-dgp-17157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεπίθετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5918 na letra ε · nº geral 17157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de invadir, de atacar. 〈εὖ, ἐπιτίθημι〉</p></section></article>\n<article id=\"entry-dgp-17158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργεσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5919 na letra ε · nº geral 17158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 boa ação; ação honesta, decente 2 beneficência 3 serviço útil; benefício 4 título ou privilégio de benfeitor. 〈εὐεργέτης〉</p></section></article>\n<article id=\"entry-dgp-17159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργετέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5920 na letra ε · nº geral 17159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. εὐεργέτουν e εὐηργέτουν, fut. εὐ­εργετήσω, aor. εὐεργέτησα, perf. εὐεργέτηκα e εὐηρ­γέτηκα) 1 fazer o bem; beneficiar; prestar um serviço a alguém, ac.: ἕκαστον εὐε. τὴν μεγίστην plat. fazer a cada um o maior bem, μεγάλως ou μεγάλα εὐε. xen. beneficiar grandemente, enormemente 2 ser benfeitor ♦ pas. 3 receber um benefício; ser beneficiado: μείζονα εὐεργετημένος xen. tendo recebido os maiores benefícios. 〈εὐεργέτης〉</p></section></article>\n<article id=\"entry-dgp-17160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργέτημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5921 na letra ε · nº geral 17160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">benefício. 〈εὐεργετέω〉</p></section></article>\n<article id=\"entry-dgp-17161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5922 na letra ε · nº geral 17161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">benfeitor. 〈εὖ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-17162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργετητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 5923 na letra ε · nº geral 17162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de εὐεργετέω.</p></section></article>\n<article id=\"entry-dgp-17163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5924 na letra ε · nº geral 17163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tende a fazer o bem; benévolo: εὐεργετικὸς πολλῶν καὶ μεγάλων artt. disposto a prestar muitos e grandes serviços 2 de benfeitor: δόξα εὐεργετική artt. reputação de benfeitor. 〈εὐεργέτης〉</p></section></article>\n<article id=\"entry-dgp-17164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργέτις, ιδος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5925 na letra ε · nº geral 17164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. -ιν (ἡ) benfeitora.</p></section></article>\n<article id=\"entry-dgp-17165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5926 na letra ε · nº geral 17165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem trabalhado; bem feito (coisa) ♦ τὰ εὐεργέα 2 boas ações; benefícios. 〈εὖ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-17166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5927 na letra ε · nº geral 17166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 eficaz; útil 2 fácil de trabalhar (coisa) 3 fem. que age bem (mulher); honesta, na expr. καὶ ἥ κ᾽ εὐεργὸς ἔῃσιν hom. mesmo a que fosse honesta. 〈εὖ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-17167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐερκῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 5928 na letra ε · nº geral 17167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. bem fechado; bem fortificado; bem defendido. 〈εὖ, ἕρκος〉</p></section></article>\n<article id=\"entry-dgp-17168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐερμής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5929 na letra ε · nº geral 17168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. afortunado; felizardo. 〈εὖ, Ἑρμῆς〉</p></section></article>\n<article id=\"entry-dgp-17169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐερμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5930 na letra ε · nº geral 17169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. boa sorte. 〈εὐερμής〉</p></section></article>\n<article id=\"entry-dgp-17170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔερος, ον, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5931 na letra ε · nº geral 17170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de bela ou boa lã; de lã espessa; rico em lã; veloso. 〈εὖ, ἔριον〉</p></section></article>\n<article id=\"entry-dgp-17171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεστώ</h1><div class=\"entry-meta\"><span>DGP · ordem 5932 na letra ε · nº geral 17171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom. e ac. -ώ, e dat. -οῖ (ἡ) bom estado; boa situação; prosperidade. 〈εὖ, ἔστω〉</p></section></article>\n<article id=\"entry-dgp-17172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐετηρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5933 na letra ε · nº geral 17172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ano bom; ano de boa colheita 2 prosperidade; abundância. 〈εὖ, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-17173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐεύρετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5934 na letra ε · nº geral 17173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de encontrar. 〈εὖ, εὑρίσκω〉</p></section></article>\n<article id=\"entry-dgp-17174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐέφοδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5935 na letra ε · nº geral 17174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de fácil acesso; fácil de atacar. 〈εὖ, ἔφοδος1〉</p></section></article>\n<article id=\"entry-dgp-17175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐζηλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5936 na letra ε · nº geral 17175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">correção (de estilo); propriedade (de linguagem). 〈εὖ, ζῆλος〉</p></section></article>\n<article id=\"entry-dgp-17176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔζυγος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5937 na letra ε · nº geral 17176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰζυγος, ος, ον bem ajustado; bem construído ou munido de bancos cômodos para os remadores (navio). 〈εὖ, ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-17177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐζωέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5938 na letra ε · nº geral 17177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">viver com felicidade; viver bem. 〈εὖ, ζωή〉</p></section></article>\n<article id=\"entry-dgp-17178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔζωμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5939 na letra ε · nº geral 17178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eruga, planta. 〈εὖ, ζωμός〉</p></section></article>\n<article id=\"entry-dgp-17179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔζωνος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5940 na letra ε · nº geral 17179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰζωνος, ος, ον 1 de bela cintura (mulher) 2 de túnica bem presa na cintura (homem) 3 ágil; alerta; disposto 4 fácil de suportar; leve (pobreza, vida).</p></section></article>\n<article id=\"entry-dgp-17180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔζωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5941 na letra ε · nº geral 17180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sem mistura; puro (vinho). 〈εὖ, ζωρός〉</p></section></article>\n<article id=\"entry-dgp-17181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐηγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5942 na letra ε · nº geral 17181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = εὐγενής.</p></section></article>\n<article id=\"entry-dgp-17182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐηγεσίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5943 na letra ε · nº geral 17182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. bom governo. 〈εὖ, ἡγέομαι〉</p></section></article>\n<article id=\"entry-dgp-17183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐήθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5944 na letra ε · nº geral 17183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 simplicidade 2 bom caráter; bondade 3 ingenuidade; simplicidade. 〈εὐήθης〉</p></section></article>\n<article id=\"entry-dgp-17184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐήθης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5945 na letra ε · nº geral 17184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de caráter simples; honesto; bom 2 ingênuo; simples; tolo ♦ τὸ εὔηθες 3 simplicidade; bondade. 〈εὖ, ἦθος〉</p></section></article>\n<article id=\"entry-dgp-17185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐηθία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5946 na letra ε · nº geral 17185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐήθεια.</p></section></article>\n<article id=\"entry-dgp-17186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐηθικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5947 na letra ε · nº geral 17186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de bom caráter; simples 2 ingênuo; tolo. 〈εὐήθης〉</p></section></article>\n<article id=\"entry-dgp-17187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐήθως</h1><div class=\"entry-meta\"><span>DGP · ordem 5948 na letra ε · nº geral 17187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com bondade; ingenuamente. 〈εὐήθης〉</p></section></article>\n<article id=\"entry-dgp-17188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐήκης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5949 na letra ε · nº geral 17188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito agudo; aguçado; pontudo (lança). 〈εὖ, ἀκή〉</p></section></article>\n<article id=\"entry-dgp-17189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐήκοος, οος, οον</h1><div class=\"entry-meta\"><span>DGP · ordem 5950 na letra ε · nº geral 17189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que presta atenção; obediente 2 inclinado a, dat. ou πρός e ac. 3 fácil de ouvir. 〈εὖ, ἀκοή〉</p></section></article>\n<article id=\"entry-dgp-17190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐηκόως</h1><div class=\"entry-meta\"><span>DGP · ordem 5951 na letra ε · nº geral 17190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com disposição para escutar; docilmente.</p></section></article>\n";
